-- Reviewed installer: one fixed administrator draft-creation RPC. No content/activation.
begin;
set local lock_timeout='3s';
create function ace.prepare_2026_practice_config(p_action text)
returns jsonb language plpgsql security definer
set search_path=pg_catalog,pg_temp set lock_timeout='3s'
as $baseline$
declare
 candidate constant jsonb := '{"id":"396d1910-d458-5d5f-8484-380bc8c71919","season_id":"23fc8eb7-2d2e-474f-b4db-c0a69f22cd62","name":"UTME practice — 2026 rules","duration_seconds":7200,"total_questions":180,"option_count":4,"composition":{"optional_subjects":{"count":3,"selection":"candidate_choice","question_count_each":40},"required_subjects":[{"subject_code":"ENG","question_count":60}]},"rules":{"option_labels":["A","B","C","D"],"duration_source":"2026 JAMB Training Manual","all_questions_required":true,"source_year":2026,"source_url":"https://jamb.gov.ng/PDFs/2026/2026%20TRAINING%20MANUAL%20%20final.pdf","configuration_basis":"owner_selected_historical_baseline","official_2027_confirmed":false,"practice_notice":"Practice follows the verified 2026 UTME format. 2027 dates and year-specific texts are unconfirmed."},"version":1,"active":false}'::jsonb;
 children constant jsonb := '[{"required":true,"sort_order":1,"subject_id":"f4a4638d-5931-49fd-8d2a-57c9dc8a37a9","question_count":60,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":101,"subject_id":"e0153c56-be67-4681-8286-4d948f651323","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":102,"subject_id":"c9477ef6-c2c5-4f62-b2e3-5c2b60a45a2b","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":103,"subject_id":"24bf2dc5-77f5-405a-b723-050ee9069eee","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":104,"subject_id":"e367a0d1-8e76-4289-bc44-bde0f01c88ae","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":105,"subject_id":"6675c55e-5f41-457c-9039-705aa089ff80","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":106,"subject_id":"1f93adfc-9967-4356-9be6-8bce6860d425","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":107,"subject_id":"c6fa4b3f-731b-4c53-ac08-290fbda8c122","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":108,"subject_id":"def40364-0c49-44e8-9ec3-a6a918e56913","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":109,"subject_id":"7787e442-6482-498b-a9c5-ce335676f612","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":110,"subject_id":"58c6db9d-8d29-449c-b635-f3833de4736b","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":111,"subject_id":"de829c17-0ff2-4524-9bf5-4fc23459d46e","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":112,"subject_id":"07783b3d-b58c-4c7f-bcbe-b3d57bfec874","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":113,"subject_id":"ce974ac5-c12f-479c-99f6-c05f16cb98a3","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":114,"subject_id":"1a2616cf-2d4a-435c-a256-ef1f39dae36b","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":115,"subject_id":"a368fb2e-8238-437d-93fc-bc1dbe4e6fd5","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":116,"subject_id":"730b1365-14ff-42f7-a12a-e19e1e4fe84b","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":117,"subject_id":"b51338b6-bd03-4fd8-814b-3d1eb53d5cc9","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":118,"subject_id":"57a5c31f-2847-43c6-82c1-7918aa1c98cc","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":119,"subject_id":"40247f5b-cbe4-4e30-835b-f71c811de685","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":120,"subject_id":"fd107ed1-a784-4443-bc46-e1f4f113c0de","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":121,"subject_id":"9be3e180-84f2-412a-bcaa-b3e002e757cc","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":122,"subject_id":"85a9ed03-731b-48bf-b0be-c6fb9903426a","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":124,"subject_id":"961e3534-3b5c-4bb1-a8f8-5291c0aa5b97","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}},{"required":false,"sort_order":125,"subject_id":"a5a5cabd-74b5-4bdd-aaf1-85b5a603f91c","question_count":40,"exam_config_id":"396d1910-d458-5d5f-8484-380bc8c71919","metadata":{"source_year":2026,"basis":"2026 UTME baseline","official_2027_confirmed":false}}]'::jsonb;
 subject_bindings constant jsonb := '[{"subject_id":"07783b3d-b58c-4c7f-bcbe-b3d57bfec874","subject_code":"GOV"},{"subject_id":"1a2616cf-2d4a-435c-a256-ef1f39dae36b","subject_code":"HIS"},{"subject_id":"1f93adfc-9967-4356-9be6-8bce6860d425","subject_code":"CRS"},{"subject_id":"24bf2dc5-77f5-405a-b723-050ee9069eee","subject_code":"ART"},{"subject_id":"40247f5b-cbe4-4e30-835b-f71c811de685","subject_code":"MAT"},{"subject_id":"57a5c31f-2847-43c6-82c1-7918aa1c98cc","subject_code":"LIT"},{"subject_id":"58c6db9d-8d29-449c-b635-f3833de4736b","subject_code":"FRE"},{"subject_id":"6675c55e-5f41-457c-9039-705aa089ff80","subject_code":"CHE"},{"subject_id":"730b1365-14ff-42f7-a12a-e19e1e4fe84b","subject_code":"IGB"},{"subject_id":"7787e442-6482-498b-a9c5-ce335676f612","subject_code":"ECO"},{"subject_id":"85a9ed03-731b-48bf-b0be-c6fb9903426a","subject_code":"POA"},{"subject_id":"961e3534-3b5c-4bb1-a8f8-5291c0aa5b97","subject_code":"YOR"},{"subject_id":"9be3e180-84f2-412a-bcaa-b3e002e757cc","subject_code":"PHY"},{"subject_id":"a368fb2e-8238-437d-93fc-bc1dbe4e6fd5","subject_code":"HEC"},{"subject_id":"a5a5cabd-74b5-4bdd-aaf1-85b5a603f91c","subject_code":"PHE"},{"subject_id":"b51338b6-bd03-4fd8-814b-3d1eb53d5cc9","subject_code":"ISS"},{"subject_id":"c6fa4b3f-731b-4c53-ac08-290fbda8c122","subject_code":"COM"},{"subject_id":"c9477ef6-c2c5-4f62-b2e3-5c2b60a45a2b","subject_code":"ARA"},{"subject_id":"ce974ac5-c12f-479c-99f6-c05f16cb98a3","subject_code":"HAU"},{"subject_id":"de829c17-0ff2-4524-9bf5-4fc23459d46e","subject_code":"GEO"},{"subject_id":"def40364-0c49-44e8-9ec3-a6a918e56913","subject_code":"CST"},{"subject_id":"e0153c56-be67-4681-8286-4d948f651323","subject_code":"AGR"},{"subject_id":"e367a0d1-8e76-4289-bc44-bde0f01c88ae","subject_code":"BIO"},{"subject_id":"f4a4638d-5931-49fd-8d2a-57c9dc8a37a9","subject_code":"ENG"},{"subject_id":"fd107ed1-a784-4443-bc46-e1f4f113c0de","subject_code":"MUS"}]'::jsonb;
 actual jsonb; result_state text; validation jsonb; source_row ace.exam_configs%rowtype;
begin
 if auth.uid() is null or not ace.is_admin() then raise exception 'Authenticated administrator context required' using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed'then raise exception 'Read committed transaction required'using errcode='25001';end if;
 if not exists(select 1 from pg_catalog.pg_roles where rolname=current_user and (rolsuper or rolbypassrls))then raise exception 'Trusted executor owner required'using errcode='42501';end if;
 perform 1 from ace.roles where user_id=auth.uid() and role='admin'for share;
 if not found then raise exception 'Authenticated administrator context required'using errcode='42501';end if;
 if p_action is null or p_action not in('check','create')then raise exception 'Invalid baseline action'using errcode='22023';end if;
 -- Parent row locks serialize absent-draft creation, activation and child authoring.
 perform 1 from ace.exam_seasons where id=(candidate->>'season_id')::uuid and code='jamb-2027'
  and exam_year=2027 and status='draft' and starts_at is null and ends_at is null for update;
 if not found then raise exception 'Preparation season drift';end if;
 perform 1 from ace.exam_seasons where id='a3e9c810-bd81-48bd-84e0-9a987e061cc7' and exam_year=2026 and status='closed'for share;
 if not found then raise exception 'Historical season drift';end if;
 select * into source_row from ace.exam_configs where id='e98b1ac1-beaa-433a-a904-54d6da2c4861'for update;
 if not found or source_row.season_id<>'a3e9c810-bd81-48bd-84e0-9a987e061cc7' or source_row.active or source_row.version<>1
 or source_row.duration_seconds<>7200 or source_row.total_questions<>180 or source_row.option_count<>4
 or source_row.composition is distinct from candidate->'composition' then raise exception 'Historical format drift';end if;
 perform id from ace.subjects where id in(select(x->>'subject_id')::uuid from jsonb_array_elements(children)x)order by id for share;
 select jsonb_agg(jsonb_build_object('subject_id',id,'subject_code',code)order by id)into actual from ace.subjects
 where active and id in(select(x->>'subject_id')::uuid from jsonb_array_elements(children)x);
 if actual is distinct from subject_bindings then raise exception 'Subject binding drift';end if;
 select jsonb_agg(jsonb_build_object('subject_id',subject_id,'required',required,'question_count',question_count,'sort_order',sort_order)order by subject_id)
 into actual from ace.exam_config_subjects where exam_config_id=source_row.id;
 if actual is distinct from(select jsonb_agg(x-'metadata'-'exam_config_id'order by x->>'subject_id')from jsonb_array_elements(children)x)then raise exception 'Historical composition drift';end if;
 perform id from ace.exam_configs where season_id=(candidate->>'season_id')::uuid order by id for update;
 select to_jsonb(c)-'created_at'into actual from ace.exam_configs c where c.id=(candidate->>'id')::uuid;
 if actual is not null and actual is distinct from candidate then raise exception 'Practice draft drift';end if;
 if exists(select 1 from ace.exam_configs where season_id=(candidate->>'season_id')::uuid and id<>(candidate->>'id')::uuid)then raise exception 'Target configuration drift';end if;
 if actual is null and p_action='create'then
  insert into ace.exam_configs(id,season_id,name,duration_seconds,total_questions,option_count,composition,rules,version,active)
  select id,season_id,name,duration_seconds,total_questions,option_count,composition,rules,version,active from jsonb_populate_record(null::ace.exam_configs,candidate);
  insert into ace.exam_config_subjects(exam_config_id,subject_id,required,question_count,sort_order,metadata)
  select exam_config_id,subject_id,required,question_count,sort_order,metadata from jsonb_populate_recordset(null::ace.exam_config_subjects,children);
  validation:=ace.validate_exam_config((candidate->>'id')::uuid);
  if validation->>'valid'is distinct from'true'then raise exception 'Practice configuration invalid';end if;
  insert into ace.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata)
  values(auth.uid(),'practice_baseline_created','exam_config',(candidate->>'id')::uuid,jsonb_build_object('source_year',2026,'source_config_id',source_row.id,'activated',false));
  result_state:='created';
 elsif actual is null then result_state:='ready';
 else result_state:='exists';end if;
 if result_state<>'ready'then
  select jsonb_agg(to_jsonb(cs)order by subject_id)into actual from ace.exam_config_subjects cs where exam_config_id=(candidate->>'id')::uuid;
  if actual is distinct from(select jsonb_agg(x order by x->>'subject_id')from jsonb_array_elements(children)x)then raise exception 'Practice composition drift';end if;
 end if;
 return jsonb_build_object('state',result_state,'config_id',candidate->>'id','source_year',2026,'subject_count',25,'active',false);
end;
$baseline$;
revoke all on function ace.prepare_2026_practice_config(text)from public,anon,authenticated;
grant execute on function ace.prepare_2026_practice_config(text)to authenticated;
commit;
